// Characterization tests: pin CURRENT behaviour of order totals, bugs included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.1, D: 100, E: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = async (items) => {
  const r = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  return { status: r.status, body: await r.json() }
}

const cases = [
  // [description, items, expected total]
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['fractional total is floored, not rounded', [{ sku: 'B', qty: 1 }], 25],
  ['exactly 100 gets no discount', [{ sku: 'D', qty: 1 }], 100],
  ['101 gets 10% off and floors (BUG-ish: cheaper than an order of 100)', [{ sku: 'A', qty: 10 }, { sku: 'C', qty: 10 }], 90],
  ['just over threshold (100.5)', [{ sku: 'D', qty: 1 }, { sku: 'B', qty: 1 }].slice(0, 1).concat([{ sku: 'C', qty: 5 }]), 90],
  ['200 -> 180', [{ sku: 'D', qty: 2 }], 180],
  ['large order 1000 -> 900', [{ sku: 'D', qty: 10 }], 900],
  ['discount applies to whole total, not just the excess', [{ sku: 'A', qty: 11 }], 99],
  ['discounted fractional total floored (33.33*4=133.32 -> 119.988)', [{ sku: 'E', qty: 4 }], 119],
  ['mixed items', [{ sku: 'A', qty: 3 }, { sku: 'B', qty: 4 }, { sku: 'D', qty: 1 }], 211.8 * 0.9 | 0],
]

for (const [name, items, total] of cases) {
  test(name, async () => {
    const { status, body } = await post(items)
    assert.equal(status, 201)
    assert.equal(body.total, total)
  })
}

test('order is retrievable with same total', async () => {
  const { body } = await post([{ sku: 'D', qty: 2 }])
  const got = await (await fetch(`${base}/orders/${body.id}`)).json()
  assert.deepEqual(got, body)
})

test('missing/empty items -> 400', async () => {
  assert.equal((await post([])).status, 400)
})

test('unknown order id returns 200 with error body (BUG-ish: not 404)', async () => {
  const r = await fetch(`${base}/orders/nope`)
  assert.equal(r.status, 200)
  assert.deepEqual(await r.json(), { error: 'not found' })
})
EOF
